import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { paths } from "../../utils/path";
import shippingAPI from "../../services/shippingService";

export default function ShippingDashboard() {
  const navigate = useNavigate();
  const [stats, setStats] = useState({
    totalShipments: 0,
    pendingShipments: 0,
    deliveredShipments: 0,
    ndrCount: 0
  });

  useEffect(() => {
    getShippingStats();
  }, []);

  const getShippingStats = async () => {
    try {
      // Get NDR count
      const ndrResponse = await shippingAPI.getNDRList({ per_page: 1000 });
      const ndrCount = ndrResponse?.data?.data?.length || 0;

      // Try to get stats from API, fallback to NDR count only
      try {
        const statsResponse = await shippingAPI.getShippingStats();
        if (statsResponse?.data?.status) {
          setStats({
            totalShipments: statsResponse.data.data.totalShipments || 0,
            pendingShipments: statsResponse.data.data.pendingShipments || 0,
            deliveredShipments: statsResponse.data.data.deliveredShipments || 0,
            ndrCount: ndrCount
          });
        }
      } catch (statsError) {
        // Fallback to just NDR count
        setStats({
          totalShipments: 0,
          pendingShipments: 0,
          deliveredShipments: 0,
          ndrCount: ndrCount
        });
      }
    } catch (error) {
      console.error("Error fetching shipping stats:", error);
    }
  };

  const shippingActions = [
    {
      title: "Create Shipment",
      description: "Create new shipment for orders",
      icon: "📦",
      path: paths?.front?.user?.shipping_create,
      color: "bg-blue-500"
    },
    {
      title: "Track Shipment",
      description: "Track existing shipments",
      icon: "🔍",
      path: paths?.front?.user?.shipping_track,
      color: "bg-green-500"
    },
    {
      title: "NDR Management",
      description: "Manage Non-Delivery Reports",
      icon: "⚠️",
      path: paths?.front?.user?.shipping_ndr,
      color: "bg-orange-500"
    },
    {
      title: "Generate Manifest",
      description: "Create shipment manifests",
      icon: "📋",
      path: paths?.front?.user?.shipping_manifest,
      color: "bg-purple-500"
    }
  ];

  return (
    <div className="shipping-dashboard">
      <h3 className="page_heading">Shipping Management</h3>

      {/* Stats Cards */}
      <div className="shipping-dashboard__stats">
        <div className="stat-card">
          <div className="stat-card__icon">📦</div>
          <div className="stat-card__content">
            <h4>{stats.totalShipments}</h4>
            <p>Total Shipments</p>
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-card__icon">⏳</div>
          <div className="stat-card__content">
            <h4>{stats.pendingShipments}</h4>
            <p>Pending Shipments</p>
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-card__icon">✅</div>
          <div className="stat-card__content">
            <h4>{stats.deliveredShipments}</h4>
            <p>Delivered</p>
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-card__icon">⚠️</div>
          <div className="stat-card__content">
            <h4>{stats.ndrCount}</h4>
            <p>NDR Reports</p>
          </div>
        </div>
      </div>

      {/* Action Cards */}
      <div className="shipping-dashboard__actions">
        <h4>Shipping Actions</h4>
        <div className="action-grid">
          {shippingActions.map((action, index) => (
            <div
              key={index}
              className="action-card"
              onClick={() => navigate(action.path)}
            >
              <div className={`action-card__icon ${action.color}`}>
                {action.icon}
              </div>
              <div className="action-card__content">
                <h5>{action.title}</h5>
                <p>{action.description}</p>
              </div>
              <div className="action-card__arrow">→</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}